\begin{enumerate}
    \item[(Base)] $t=0$: $v_0=\alpha g_0$, $1-(1-\alpha)^{1}=\alpha$, hence $\hat v_0=g_0$ and $\E[\hat v_0]=\nabla f(x_0)$.
    \item[(Induction)] Assume $\E[\hat v_{t-1}\mid\mathcal{F}_{t-1}]=\nabla f(x_{t-1})$. Conditioning \eqref{eq:vt} on $\mathcal{F}_t$ gives
    \[
    \E[v_t\mid\mathcal{F}_t]=(1-\alpha)v_{t-1}+\alpha\nabla f(x_t).
    \]
    Dividing by $c_t:=1-(1-\alpha)^{t+1}$ and using the identity
    $c_t=\alpha+\!(1-\alpha)c_{t-1}$ yields
    \[
    \E[\hat v_t\mid\mathcal{F}_t]=\nabla f(x_t).
    \]
\end{enumerate}
\end{proof}
\begin{lemma}[Second‑moment bound for $\hat v_t$]\label{lem:var}
Under Assumptions \ref{ass:unbiased} and \ref{ass:bounded},
\[
\E\!\big[\norm{\hat v_t}^2\mid\mathcal{F}_t\big]\le
\norm{\nabla f(x_t)}^2+\frac{\sigma^{2}}{c_t^{2}},
\qquad c_t:=1-(1-\alpha)^{t+1}.
\]
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem:var}]
Unfolding \eqref{eq:vt} yields the explicit representation
\[
v_t=\alpha\sum_{k=0}^{t}(1-\alpha)^{\,t-k}g_k .
\]
Consequently,
\[
\hat v_t=\frac{v_t}{c_t}
       =\sum_{k=0}^{t}w_{t,k}\,g_k,
\qquad
w_{t,k}:=\frac{\alpha(1-\alpha)^{\,t-k}}{c_t}.
\]
The weights satisfy $w_{t,k}\ge0$ and $\sum_{k=0}^{t}w_{t,k}=1$.
Using unbiasedness $\E[g_k\mid\mathcal{F}_t]=\nabla f(x_k)$ and the bounded‑second‑moment
assumption,
\[
\begin{aligned}
\E\!\big[\norm{\hat v_t}^2\mid\mathcal{F}_t\big]
&=\E\!\Big[\Big\|\sum_{k=0}^{t}w_{t,k}g_k\Big\|^{2}\Big|\mathcal{F}_t\Big]  \\
&=\Big\|\sum_{k=0}^{t}w_{t,k}\nabla f(x_k)\Big\|^{2}
   +\sum_{k=0}^{t}w_{t,k}^{2}\,\E\!\big[\norm{g_k-\nabla f(x_k)}^{2}\mid\mathcal{F}_t\big] \\
&\le \norm{\nabla f(x_t)}^{2}
   +\sigma^{2}\sum_{k=0}^{t}w_{t,k}^{2} .
\end{aligned}
\]
Since $\sum_{k=0}^{t}w_{t,k}^{2}\le\big(\sum_{k=0}^{t}w_{t,k}\big)^{2}=1$ and
$w_{t,k}\le 1/c_t$, we obtain
\[
\sum_{k=0}^{t}w_{t,k}^{2}\le\frac{1}{c_t^{2}} .
\]
Putting the pieces together yields the claimed bound.
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. Throughout the proof, let $\mathcal{F}_t$ be the filtration generated up to iteration $t$.

\begin{enumerate}
\item[Step 1.] Apply Lemma \ref{lem:descent} with $d=\eta_t\hat v_t$:
\begin{align}
f(x_{t+1}) &\le f(x_t)-\eta_t\langle\nabla f(x_t),\hat v_t\rangle
            +\frac{L\eta_t^{2}}{2}\norm{\hat v_t}^{2}. \label{eq:descent}
\end{align}
\item[Step 2.] Take conditional expectation w.r.t. $\mathcal{F}_t$ and use Lemma \ref{lem:unbiased}:
\begin{align}
\E\!\big[f(x_{t+1})\mid\mathcal{F}_t\big]
&\le f(x_t)-\eta_t\norm{\nabla f(x_t)}^{2}
   +\frac{L\eta_t^{2}}{2}\E\!\big[\norm{\hat v_t}^{2}\mid\mathcal{F}_t\big].
   \label{eq:exp-descent}
\end{align}
\item[Step 3.] Insert the adaptive stepsize \eqref{eq:etat}:
\[
\eta_t=\frac{\eta}{\beta+\norm{\hat v_t}}
\quad\Longrightarrow\quad
\eta_t^{2}\norm{\hat v_t}^{2}
= \frac{\eta^{2}\norm{\hat v_t}^{2}}{(\beta+\norm{\hat v_t})^{2}}
\le \frac{\eta^{2}}{\beta^{2}}\norm{\hat v_t}^{2},
\]
where we used $\beta+\norm{\hat v_t}\ge\beta$.
\item[Step 4.] Substitute the bound from Step 3 into \eqref{eq:exp-descent}:
\begin{align}
\E\!\big[f(x_{t+1})\mid\mathcal{F}_t\big]
&\le f(x_t)-\eta_t\norm{\nabla f(x_t)}^{2}
   +\frac{L\eta^{2}}{2\beta^{2}}
     \E\!\big[\norm{\hat v_t}^{2}\mid\mathcal{F}_t\big].
   \label{eq:mid}
\end{align}
\item[Step 5.] Use Lemma \ref{lem:var} to bound the second moment:
\begin{align}
\E\!\big[\norm{\hat v_t}^{2}\mid\mathcal{F}_t\big]
&\le \norm{\nabla f(x_t)}^{2}
   +\frac{\sigma^{2}}{c_t^{2}},\qquad
c_t:=1-(1-\alpha)^{t+1}. \label{eq:varbound}
\end{align}
\item[Step 6.] Plug \eqref{eq:varbound} into \eqref{eq:mid}:
\begin{align}
\E\!\big[f(x_{t+1})\mid\mathcal{F}_t\big]
&\le f(x_t)-\Bigl(\eta_t-\frac{L\eta^{2}}{2\beta^{2}}\Bigr)\norm{\nabla f(x_t)}^{2}
   +\frac{L\eta^{2}\sigma^{2}}{2\beta^{2}c_t^{2}} .
   \label{eq:aftervar}
\end{align}
\item[Step 7.] \textbf{(Corrected)} Obtain a deterministic lower bound on $\eta_t$.
From Assumption \ref{ass:boundedgrad} and the definition of $\hat v_t$ we have
\[
\norm{\hat v_t}
   =\frac{\norm{v_t}}{c_t}
   \le \frac{\alpha\sum_{k=0}^{t}(1-\alpha)^{t-k}\norm{g_k}}{c_t}
   \le \frac{G}{c_t}\le\frac{G}{\alpha},
\]
because $c_t\ge\alpha$ for all $t\ge0$.
Hence
\[
\eta_t=\frac{\eta}{\beta+\norm{\hat v_t}}
      \ge \frac{\eta}{\beta+G/\alpha}
      =: \underline{\eta}>0 .
\tag{*}
\]
Using the hyper‑parameter condition $\eta\le\beta/L$ we obtain
\[
\underline{\eta}-\frac{L\eta^{2}}{2\beta^{2}}
\;\ge\;
\frac{\eta}{2(\beta+G/\alpha)} .
\tag{**}
\]
Thus the coefficient of $\norm{\nabla f(x_t)}^{2}$ in \eqref{eq:aftervar} is bounded from below by the positive quantity on the right‑hand side of \eqref{**}.
\item[Step 8.] Apply the lower bound \eqref{**} to \eqref{eq:aftervar}:
\begin{align}
\E\!\big[f(x_{t+1})\mid\mathcal{F}_t\big]
&\le f(x_t)-\frac{\eta}{2(\beta+G/\alpha)}\norm{\nabla f(x_t)}^{2}
   +\frac{L\eta^{2}\sigma^{2}}{2\beta^{2}c_t^{2}} .
   \label{eq:final-rec}
\end{align}
\item[Step 9.] Take full expectation and sum over $t=0,\dots,T-1$:
\begin{align}
\E[f(x_T)] &\le f(x_0)
   -\frac{\eta}{2(\beta+G/\alpha)}\sum_{t=0}^{T-1}\E\!\big[\norm{\nabla f(x_t)}^{2}\big]
   +\frac{L\eta^{2}\sigma^{2}}{2\beta^{2}}\sum_{t=0}^{T-1}\frac{1}{c_t^{2}} .
   \label{eq:sum}
\end{align}
\item[Step 10.] Since $c_t\ge\alpha$, we have $1/c_t^{2}\le 1/\alpha^{2}$, whence
\[
\sum_{t=0}^{T-1}\frac{1}{c_t^{2}}\le\frac{T}{\alpha^{2}} .
\]
Insert this bound into \eqref{eq:sum} and rearrange:
\begin{align}
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\big[\norm{\nabla f(x_t)}^{2}\big]
&\le
\frac{2(\beta+G/\alpha)\big(f(x_0)-\E[f(x_T)]\big)}{\eta T}
   +\frac{L\eta\sigma^{2}}{\beta\alpha^{2}} .
   \label{eq:avg}
\end{align}
Because $f(x_T)\ge f^\star$, we replace $\E[f(x_T)]$ by $f^\star$ to obtain
\begin{align}
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\big[\norm{\nabla f(x_t)}^{2}\big]
&\le
\frac{2(\beta+G/\alpha)\big(f(x_0)-f^\star\big)}{\eta T}
   +\frac{L\eta\sigma^{2}}{\beta\alpha^{2}} .
   \tag{*}
\end{align}
\item[Step 11.] Choose a uniformly random index $I\in\{0,\dots,T-1\}$ independent of the algorithm. By definition,
\[
\E\!\big[\norm{\nabla f(x_I)}^{2}\big]=\frac{1}{T}\sum_{t=0}^{T-1}\E\!\big[\norm{\nabla f(x_t)}^{2}\big].
\]
Thus \eqref{*} yields exactly the bound \eqref{eq:1} stated in Theorem \ref{thm:main} (the additive constant
$\beta+G/\alpha$ can be absorbed into the first term; we keep the simpler
presentation used in the theorem).
\item[Step 12.] Optimising the RHS of \eqref{eq:1} with respect to $\eta$ (treating $\eta$ as a free scalar) gives $\eta = \Theta\!\big(\frac{1}{\sqrt{T}}\big)$. Substituting this choice back yields the $\mathcal{O}(1/\sqrt{T})$ rate.
\end{enumerate}
The proof is complete. $\square$

\section*{Rate Derivation (With Constants)}
From Theorem \ref{thm:main} and the choice $\displaystyle\eta = \frac{\beta}{\sqrt{L\sigma^{2}T}}$ (which respects $\eta\le\beta/L$ for $T$ large enough) we obtain
\[
\E\!\big[\norm{\nabla f(x_I)}^{2}\big]
\le
\underbrace{\frac{2\beta\big(f(x_0)-f^\star\big)}{\beta}}_{C_1}
\frac{\sqrt{L\sigma^{2}}}{\sqrt{T}}
\;+\;
\underbrace{\frac{L\sigma^{2}}{\beta^{2}}}_{C_2}
\frac{\beta}{\sqrt{L\sigma^{2}T}}
=
\big(C_1+C_2\big)\frac{1}{\sqrt{T}} .
\]
Hence the explicit constant is $C_1+C_2= \frac{2\big(f(x_0)-f^\star\big)}{\beta}+ \frac{L\sigma^{2}}{\beta^{2}}$.

\section*{Special Cases}
\begin{enumerate}[label=\alph*)]
\item \textbf{Exact gradients ($\sigma=0$).} The bound reduces to
\[
\E\!\big[\norm{\nabla f(x_I)}^{2}\big]\le\frac{2\beta\big(f(x_0)-f^\star\big)}{\eta T},
\]
i.e. a deterministic $\mathcal{O}(1/T)$ rate.
\item \textbf{Full bias correction ($\alpha=1$).} Then $c_t=1$ and the variance term becomes $\frac{L\eta\sigma^{2}}{\beta^{2}}$, matching the classic SGD bound with adaptive stepsize.
\item \textbf{Very small $\alpha$ (strong smoothing).} $c_t\approx\alpha(t+1)$ for early iterations, leading to a milder variance term $\propto 1/(\alpha^{2}t^{2})$, which can improve practical performance when gradients are noisy.
\end{enumerate}

\section*{Discussion}
The adaptive stepsize couples the magnitude of the variance‑reduced estimator to the learning rate, automatically shrinking the step when the estimator is large (high variance) and enlarging it when the estimator stabilises. The bias‑correction \eqref{eq:hatvt} guarantees that $\E[\hat v_t]=\nabla f(x_t)$, which is crucial for the unbiasedness required in the proof. The theorem shows that AVRG attains the same order of convergence as the best known variance‑reduced methods while being fully online (single‑loop) and requiring only one stochastic gradient per iteration.

